  function trailCards(){return `<div class="section-heading"><h2>Research trails</h2><span class="tiny dim">Enter a focused network</span></div><section class="trail-grid">${(D.research_trails||[]).map((t,i)=>`<button class="trail-card" data-trail="${esc(t.id)}"><span class="mono tiny dim">0${i+1} / NETWORK</span><h3>${esc(t.title)}</h3><p>${esc(t.description)}</p><span class="trail-arrow">Explore connections ↗</span></button>`).join('')}</section>`;}

  function expansionRibbon(){const a=D.audit,f=D.final_audit,l=D.closure_review||D.sweep_review||D.limits_review;if(!a)return '';return `<div class="expansion-ribbon"><div><span class="small-caps">${D.closure_review?'FINAL ACCOUNTING':D.sweep_review?'COVERAGE & RESEARCH PASS':l?'REMAINING LIMITS REVIEW':'COVERAGE REVIEW'} · EDITION ${esc(l?.edition||a.edition||3)}</span><h3>${fmt(a.after.semantic_relations)} typed relationships</h3><p>${fmt(D.documents.filter(d=>d.url).length)} source links · ${l?`${fmt(l.reviewed_total)} review dispositions`:`${fmt(f?.reviewed_total||0)} Edition 3 audit dispositions`}</p></div><div><strong>${fmt(a.after.ss_neighbors)}</strong><span>direct SS connections<br>across both evidence layers</span></div><a class="button compact" href="#coverage">${l?'Explore the latest findings':'Explore the Edition 3 audit'} →</a></div>`;}

  function claimFilterNotice(){return state.claimEntity||state.edgeFilter==='unlinked'||state.insightClaimIds?`<div class="notice"><span>⌕</span><p>${state.insightClaimIds?`Chart selection: <strong class="insight-filter-label">${esc(state.insightLabel)}</strong>. ${fmt(state.insightClaimIds.size)} linked claims before additional filters. `:''}${state.claimEntity?`Showing all records linked to <strong>${esc(E[state.claimEntity]?.name)}</strong>, including aliases.`:''}${state.edgeFilter==='unlinked'?'Showing records without a typed relationship. Some are literal or descriptive statements.':''}</p><button class="text-button" data-action="clear-claim-scope">Clear record filter</button></div>`:'';}

  const graphScopeCache=new Map();
