  function network(){return heading('KNOWLEDGE GRAPH','Every connection has a source.','Explore a neighborhood, follow a direction, and inspect the evidence behind each relationship. Values count unique claims in the selected corpus.',`<button class="button" data-action="export-graph">↓ Export GraphML</button>`)+filters()+`<div class="network-search"><label for="graph-search" class="small-caps">GO DIRECTLY TO AN ENTITY</label><div><input class="field" id="graph-search" list="entity-options" aria-label="Find an entity in the graph" placeholder="Try SS, Hans Kammler, Otto Skorzeny, Puharich…" value="${esc(E[state.selectedEntity]?.name||'')}"><button class="button primary" data-action="focus-search">Open neighborhood ↗</button></div><div class="trail-shortcuts">${(D.research_trails||[]).map(t=>`<button class="text-button" data-trail="${esc(t.id)}">${esc(t.title)}</button>`).join('')}</div></div><div class="toolbar graph-toolbar"><select class="select" id="graph-kind" aria-label="Relationship view"><option value="assertion" ${state.graphKind==='assertion'?'selected':''}>Directed relationships</option><option value="cooccurrence" ${state.graphKind==='cooccurrence'?'selected':''}>Shared claim appearances</option></select><select class="select" id="graph-limit" aria-label="Maximum visible nodes">${[60,100,200,400,1000,5000].map(n=>`<option value="${n}" ${state.graphLimit===n?'selected':''}>${n===5000?'All matched entities':'Up to '+n+' entities'}</option>`).join('')}</select><select class="select" id="graph-depth" aria-label="Neighborhood depth"><option value="0" ${state.graphDepth===0?'selected':''}>Whole collection</option><option value="1" ${state.graphDepth===1?'selected':''}>One step from selection</option><option value="2" ${state.graphDepth===2?'selected':''}>Two steps from selection</option></select><label class="graph-values-toggle"><input id="graph-values" type="checkbox" ${state.graphValues?'checked':''}> Edge values</label><span class="result-summary" id="graph-count" aria-live="polite"></span></div><div class="network-layout graph-workbench"><div class="panel network-panel"><div class="panel-header"><div class="graph-legend">${['person','organization','place','work','concept'].map(t=>`<span><i class="legend-dot" data-node-color="${t}" style="background:${color(t)}"></i>${title(t)}</span>`).join('')}</div><button class="text-button" data-action="expand-map">Expand map ⛶</button><div class="graph-evidence-key"><span><i class="edge-swatch"></i>Conversation</span><span><i class="edge-swatch research"></i>Documentary research</span><span><b class="edge-value-swatch">3</b>Unique supporting claims</span></div></div><div class="graph-stage"><canvas id="network-canvas" tabindex="0" aria-label="Interactive directed relationship graph" aria-describedby="graph-accessibility"></canvas><div class="graph-map-status"><span class="graph-status-dot"></span><span id="graph-layout-status">Preparing map</span></div><div class="graph-controls"><button class="icon-button" data-graph-zoom="1.25" aria-label="Zoom in">+</button><button class="icon-button" data-graph-zoom="0.8" aria-label="Zoom out">−</button><button class="icon-button" data-action="fit-graph" aria-label="Fit graph">⌖</button><button class="icon-button" data-action="center-selection" aria-label="Center selected entity">◎</button></div><div class="graph-tooltip graph-rich-tooltip" id="graph-tooltip" role="tooltip" hidden></div><div class="graph-hint">SCROLL TO ZOOM · DRAG TO PAN · CLICK A NODE OR ARROW</div></div><div class="panel-footer"><div><span id="graph-edge-count"></span><small class="graph-value-note">Node size: linked claims · Edge width and value: supporting claims</small></div><button class="text-button" data-action="show-relationship-register">Accessible connection register ↓</button></div><details class="graph-performance"><summary>Map performance</summary><output id="graph-performance" aria-live="off">Preparing renderer</output></details><div class="graph-scope-note" id="graph-edge-kind">${graphModeNote()}</div><p class="sr-only" id="graph-accessibility">Use the entity search and connected-entity buttons to navigate. On the map, arrow keys pan, plus and minus zoom, zero fits the map, and Enter opens the selected entity dossier. The complete connection register below provides a keyboard-accessible alternative to the canvas and is independent of the visible node limit.</p></div><aside class="panel network-inspector" aria-label="Selected entity and path finder"><div class="panel-header"><h2>Entity inspector</h2></div><div class="panel-body" id="entity-inspector"></div><div class="path-box"><h3>Find a connection</h3><input class="field" id="path-from" list="entity-options" aria-label="Path starting entity" placeholder="From entity…" value="${esc(E[state.path[0]]?.name||'')}"><input class="field" id="path-to" list="entity-options" aria-label="Path destination entity" placeholder="To entity…" value="${esc(E[state.path.at(-1)]?.name||'')}"><datalist id="entity-options">${graphIndex().nodes.map(e=>`<option value="${esc(e.name)}">${esc((e.aliases||[]).join(', '))}</option>`).join('')}</datalist><button class="button compact" data-action="find-path" style="width:100%">Trace shortest connection →</button><div id="path-result">${state.path.length?pathMarkup(state.path):''}</div><p class="note" style="font-size:10px;margin:12px 0 0">Paths traverse relationships in either direction. Every step retains its original arrows and evidence; a route does not imply that its endpoints share a role.</p></div></aside></div><section id="relationship-register">${relationshipRegister()}</section>`;}
  const graphModeNote=()=>state.graphKind==='assertion'?'Each arrow groups one exact subject → predicate → object. Values count distinct supporting claim records, not confidence or independent corroboration. Select an arrow for its sources.':'Shared appearances connect entities named in the same indexed claim. Values count those claims; this view does not assert a direct relationship, direction, or membership.';
  function relationshipSource(r){const c=r.c,url=safeURL(r.evidence_url||c.video_source_locator||S[c.source_id]?.url);return `<span class="source-short">${esc(sourceLabel(c.source_id))}</span><a class="time-link" href="${url}" target="_blank" rel="noopener noreferrer">${isContext(c)?'Open cited document':time(r.youtube_start??c.youtube_start)} ↗</a><span class="source-clock">${isContext(c)?esc(title(S[c.source_id]?.source_kind)):'Relationship’s native caption passage'}</span>`;}
  function relationshipRows(){return graphIndex().rows;}
  function filteredRelationships(){const index=graphIndex(),rows=state.relationScope==='selected'&&state.selectedEntity?(index.rowByEntity.get(state.selectedEntity)||[]):index.rows,q=state.relationQ.trim().toLowerCase();return q?rows.filter(r=>r.search.includes(q)):rows;}
  function relationshipRegister(){const rows=filteredRelationships(),g=graphIndex().graph('assertion'),size=40;state.relationPage=Math.max(1,Math.min(state.relationPage,Math.ceil(rows.length/size)||1));const batch=rows.slice((state.relationPage-1)*size,state.relationPage*size);return `<div class="section-heading"><div><h2>Complete connection register</h2><p class="note">${fmt(rows.length)} directed relationship records, independent of the map’s node limit. Support values apply to the exact directed triple in the selected corpus.</p></div><button class="button compact" data-action="export-relations">↓ Export relationship CSV</button></div><div class="toolbar"><input class="field search-field" id="relation-search" value="${esc(state.relationQ)}" type="search" placeholder="Search a person, role, institution, or record…" aria-label="Search relationships"><select class="select" id="relation-scope" aria-label="Relationship register scope"><option value="selected" ${state.relationScope==='selected'?'selected':''}>${state.selectedEntity?'Connected to '+esc(E[state.selectedEntity]?.name):'All selected records'}</option><option value="all" ${state.relationScope==='all'?'selected':''}>Entire selected corpus</option></select><span class="tiny dim">Subject → role → object</span></div><div class="panel">${rows.length?`<div class="data-table-wrap"><table class="data-table relationship-table"><thead><tr><th>SUBJECT</th><th>RELATIONSHIP</th><th>OBJECT</th><th>SUPPORT</th><th>EVIDENCE</th></tr></thead><tbody>${batch.map(r=>{const edge=g.edgeById.get(AtlasGraph.tripleKey(r.subject_id,r.predicate||'states',r.object_id));return `<tr><td>${eButton(r.subject_id)}</td><td><button class="row-button" data-claim="${esc(r.c.id)}">${esc(r.predicate.replaceAll('_',' '))}</button>${r.text?`<p class="note">${esc(r.text)}</p>`:''}</td><td>${eButton(r.object_id)}</td><td>${edge?`<button class="graph-support-value" data-graph-edge="${esc(edge.id)}" data-edge-kind="assertion" aria-label="Inspect ${edge.value} supporting claims and ${edge.source_count} source records"><strong>${fmt(edge.value)}</strong><span>claim${edge.value===1?'':'s'}<small>${fmt(edge.source_count)} source${edge.source_count===1?'':'s'}</small></span></button>`:''}</td><td>${layerPill(r.c)}<div style="margin-top:8px">${relationshipSource(r)}</div><button class="text-button tiny" data-connection="${esc(r.subject_id+'|'+r.object_id)}">All roles for this pair ↗</button></td></tr>`;}).join('')}</tbody></table></div>${pagination(rows.length,size,state.relationPage,'relations')}`:empty('No typed relationships in this selection.','Try the whole corpus or a broader search. Mention-only references remain in entity dossiers and the shared-appearance map.')}</div>`;}
  function refreshRelationRegister(){const el=$('#relationship-register');if(el)el.innerHTML=relationshipRegister();}
  function graphEdgeMetrics(edge){return `<div class="edge-evidence-metrics"><div><strong>${fmt(edge.value)}</strong><span>unique supporting claim${edge.value===1?'':'s'}</span></div><div><strong>${fmt(edge.source_count)}</strong><span>distinct source record${edge.source_count===1?'':'s'}</span></div>${edge.directed?`<div><strong>${fmt(edge.record_count)}</strong><span>relationship extraction${edge.record_count===1?'':'s'}</span></div>`:''}</div>`;}
  function graphEdgeEvidence(edge){return edge.claim_ids.map(id=>{const c=C[id];if(!c)return '';const rows=(edge.rows||[]).filter(r=>r.c.id===id);return `<section class="drawer-section connection-evidence">${layerPill(c)} ${statusPill(c)}${rows.map(r=>`${r.text?`<p>${esc(r.text)}</p>`:''}${r.note||r.ambiguity?`<p class="coverage-note">${esc(r.note||r.ambiguity)}</p>`:''}${edgeEvidence(r,c)}`).join('')}${recordCard(c)}</section>`;}).join('');}
  function openGraphEdge(id,kind=state.graphKind){const edge=typeof id==='object'?id:graphIndex().graph(kind).edgeById.get(id);if(!edge)return;drawer(drawerHead(edge.directed?'DIRECTED RELATIONSHIP':'SHARED CLAIM APPEARANCE',`${E[edge.a]?.name} ${edge.directed?'→':'↔'} ${E[edge.b]?.name}`)+`<div class="triple">${eButton(edge.a)}<span class="triple-predicate">${esc(edge.predicate.replaceAll('_',' '))}</span>${eButton(edge.b)}</div>${graphEdgeMetrics(edge)}<p class="coverage-note">${edge.directed?'Only the same subject, predicate, and object are aggregated here. Duplicate extractions within one claim count once.':'These entities appear in the same indexed claims. No direct relationship or direction is inferred.'} Source counts identify distinct indexed sources; repeated accounts can share an origin. These values measure evidence volume, not truth or confidence.</p><div class="edge-source-list"><h3>Source records</h3>${edge.source_ids.map(id=>`<span class="pill">${esc(sourceLabel(id))}</span>`).join('')}</div>${edge.directed?`<div class="drawer-actions"><button class="button compact" data-connection="${esc(edge.a+'|'+edge.b)}">Inspect all roles between these entities →</button></div>`:''}${graphEdgeEvidence(edge)}`);}
  function openConnection(a,b,kind='assertion'){
    const g=graphIndex().graph(kind),pair=g.pairs.get(AtlasGraph.pairKey(a,b));if(!pair){drawer(drawerHead('CONNECTION EVIDENCE',`${E[a]?.name} ↔ ${E[b]?.name}`)+'<p class="note">No relationship is indexed for this pair in the selected corpus.</p>');return;}
    if(kind==='cooccurrence'){openGraphEdge(pair.edges[0],kind);return;}
    drawer(drawerHead('ALL DIRECTED ROLES',`${E[a]?.name} ↔ ${E[b]?.name}`)+`<div class="edge-evidence-metrics"><div><strong>${fmt(pair.value)}</strong><span>unique claims across this pair</span></div><div><strong>${fmt(pair.source_count)}</strong><span>distinct source records</span></div><div><strong>${fmt(pair.edges.length)}</strong><span>directed triples</span></div></div><p class="note">Different roles and directions stay separate. A claim supporting more than one role is counted once in the pair total.</p>${pair.edges.map(edge=>`<section class="drawer-section"><div class="triple">${eButton(edge.a)}<span class="triple-predicate">${esc(edge.predicate.replaceAll('_',' '))}</span>${eButton(edge.b)}</div><button class="graph-edge-open" data-graph-edge="${esc(edge.id)}" data-edge-kind="assertion"><strong>${fmt(edge.value)} claim${edge.value===1?'':'s'}</strong><span>${fmt(edge.source_count)} source${edge.source_count===1?'':'s'} · inspect this direction →</span></button>${edge.claim_ids.map(id=>C[id]?recordCard(C[id]):'').join('')}</section>`).join('')}`);
  }
  function focusEntity(id,depth=1,seeds=[]){if(!E[id])return;state.selectedEntity=id;state.graphDepth=depth;state.graphSeeds=seeds;state.path=[];state.neighborQ='';state.neighborPage=1;state.relationPage=1;state.relationQ='';state.relationScope='selected';if(!$('#detail-drawer').hidden)closeDrawer();if(state.view==='network'){if(graphInstance?.scopeKey!==graphScopeKey()||graphInstance?.kind!==state.graphKind)render();else{$('#graph-search').value=E[id].name;$('#graph-depth').value=String(depth);$('#path-result').innerHTML='';updateNetworkGraph({fit:true});inspector();refreshRelationRegister();updateGraphLocation();}}else location.hash='network';}
  function openTrail(id){const t=D.research_trails?.find(t=>t.id===id);if(!t||!t.seed_ids.length)return;state.source='all';state.layer='all';state.graphKind='assertion';state.graphLimit=400;focusEntity(t.focus_id||t.seed_ids[0],t.depth||1,t.seed_ids);if($('#graph-limit'))$('#graph-limit').value=String(state.graphLimit);}
  function allEdges(kind=state.graphKind){return graphIndex().graph(kind).edges;}
  function inspector(){const el=$('#entity-inspector');if(!el)return;const e=E[state.selectedEntity];if(!e){el.innerHTML='<div class="entity-avatar large">↗</div><h3>Start with a name</h3><p class="note">Search above, choose a research trail, or select a node. Every entity in the selected corpus remains searchable beyond the visible map.</p><div class="graph-inspector-guide"><strong>Read a connection</strong><p>Arrowheads show direction. The number on an edge counts unique supporting claims. Select it to inspect its predicate, sources, and attribution.</p></div>';return;}
    const index=graphIndex(),g=index.graph(state.graphKind),all=[...(g.adjacency.get(e.id)?.values()||[])].sort((a,b)=>b.value-a.value||a.id.localeCompare(b.id)),pairs=all.filter(x=>matches(E[x.a===e.id?x.b:x.a],state.neighborQ)),size=15;state.neighborPage=Math.max(1,Math.min(state.neighborPage,Math.ceil(pairs.length/size)||1));const batch=pairs.slice((state.neighborPage-1)*size,state.neighborPage*size),cs=index.claimsByEntity.get(e.id)||[];
    el.innerHTML=`<div class="entity-avatar large" style="color:${color(e.type)}">${esc(initials(e.name))}</div><h3>${esc(e.name)}</h3><span class="pill">${esc(title(e.type))}</span><div class="inspector-actions"><button class="text-button" data-entity="${esc(e.id)}">Full dossier ↗</button><button class="text-button" data-search-entity="${esc(e.id)}">All linked claims →</button></div><div class="inspector-kv"><span>Linked claims</span><strong>${fmt(cs.length)}</strong><span>Direct neighbors</span><strong>${fmt(all.length)}</strong><span>Documentary claims</span><strong>${fmt(cs.filter(isContext).length)}</strong></div><div class="small-caps">ALL CONNECTED ENTITIES</div><input class="field neighbor-search" id="neighbor-search" value="${esc(state.neighborQ)}" placeholder="Filter connected names…" aria-label="Filter connected entities"><div class="neighbor-list">${batch.map(x=>{const other=E[x.a===e.id?x.b:x.a],primary=x.edges.slice().sort((a,b)=>b.value-a.value)[0];return `<div class="neighbor-row"><button class="connection" data-graph-entity="${esc(other.id)}"><i class="legend-dot" data-node-color="${esc(other.type)}" style="background:${color(other.type)}"></i>${esc(other.name)}<small title="Unique supporting claims">${fmt(x.value)}</small></button><button class="neighbor-evidence" ${state.graphKind==='assertion'?'data-connection':'data-shared-connection'}="${esc(e.id+'|'+other.id)}">${state.graphKind==='assertion'?(primary.a===e.id?'→ ':'← ')+esc(primary.predicate.replaceAll('_',' ')):'Shared claim appearance'}${x.edges.length>1?' +'+(x.edges.length-1)+' directed roles':''} · ${fmt(x.source_count)} source${x.source_count===1?'':'s'} ↗</button></div>`;}).join('')||'<p class="note">No matching connections. Try shared appearances or another evidence layer.</p>'}</div>${pairs.length>size?`<div class="neighbor-pagination"><button class="icon-button" data-neighbor-page="${state.neighborPage-1}" ${state.neighborPage===1?'disabled':''} aria-label="Previous connected entities">←</button><span>${(state.neighborPage-1)*size+1}–${Math.min(state.neighborPage*size,pairs.length)} / ${pairs.length}</span><button class="icon-button" data-neighbor-page="${state.neighborPage+1}" ${state.neighborPage*size>=pairs.length?'disabled':''} aria-label="Next connected entities">→</button></div>`:''}`;
  }
  function mountNetwork(){graphInstance=makeGraph($('#network-canvas'),{limit:state.graphLimit});inspector();}
